  if(!record(schema)||schema.type!=='object'||schema.additionalProperties!==false||!record(schema.properties)
    ||!Array.isArray(schema.required)||!schema.required.includes('role_interpretation')
    ||(!['mission-director-proposal/4','mission-director-joint-witness/1'].includes(single(schema.properties.schema_version))&&!idWire&&!numericWire))return false;
  if(idWire&&Object.keys(schema.properties.schema_version).length!==2)return false;
  if(numericWire){
    const closed=(n,keys)=>record(n)&&n.type==='object'&&n.additionalProperties===false&&record(n.properties)&&Object.keys(n.properties).length===keys.length&&keys.every(k=>Object.hasOwn(n.properties,k))&&Array.isArray(n.required)&&n.required.length===keys.length&&keys.every(k=>n.required.includes(k));
    const globals=['schema_version','source_window_id','source_evidence','selection','world_reaction_intent','profile_audit','progression','role_interpretation'];
    if(!closed(schema,globals)||Object.keys(schema.properties.schema_version).length!==2||!uuid(single(schema.properties.source_window_id)))return false;
    const role=schema.properties.role_interpretation,choice=schema.properties.selection,progress=schema.properties.progression;
    if(!closed(role,['p0','p1'])||!record(choice)||!Array.isArray(choice.anyOf)||!choice.anyOf.length
      ||choice.anyOf.some(c=>!closed(c,['v','b','n']))
