      ||progress.anyOf.some(c=>!closed(c,['i','m'])))return false;
    for(const name of ['p0','p1']){
      const row=role.properties[name];if(!record(row)||!Array.isArray(row.anyOf)||row.anyOf.length!==9)return false;
      for(let n=0;n<9;n++){const variant=row.anyOf[n],keys=Array.from({length:n},(_,i)=>'d'+i);if(!closed(variant,['u'+n,...keys]))return false;const gaps=variant.properties['u'+n];if(!record(gaps)||gaps.type!=='array'||gaps.minItems!==(n?0:1)||gaps.maxItems!==8-n)return false;const peer2=wire.startsWith('mission-director-peer-confirmation/2:');if(peer2?(!closed(gaps.items,['g','q'])||gaps.items.properties.g?.type!=='integer'||gaps.items.properties.g.minimum!==0||gaps.items.properties.g.maximum!==n||!record(gaps.items.properties.q)):(gaps.items?.type!=='integer'||gaps.items.minimum!==0||gaps.items.maximum!==n))return false;}
    }
    const defs=schema.$defs;if(!record(defs)||Object.keys(defs).length<1||Object.keys(defs).length>1000)return false;
    return Object.keys(defs).every(name=>/^n[0-9]{1,3}$/.test(name)&&record(defs[name]));
  }
