    const keys=['current_intent','movement_role_ids','guidance_fato_id','guidance_quote'];
    if(Object.hasOwn(schema.properties,'opportunity_id')||Object.hasOwn(schema.properties,'action_kind')
      ||!schema.required.includes('selection')||!record(choice)||!Array.isArray(choice.anyOf)||choice.anyOf.length<1
      ||!record(g)||g.type!=='object'||g.additionalProperties!==false||!record(g.properties)
      ||Object.keys(g.properties).length!==keys.length||!keys.every(k=>Object.hasOwn(g.properties,k))
      ||!Array.isArray(g.required)||g.required.length!==keys.length||!keys.every(k=>g.required.includes(k)))return false;
    if(choice.anyOf.some(c=>!record(c)||c.type!=='object'||c.additionalProperties!==false||!record(c.properties)
      ||Object.keys(c.properties).length!==3||!['opportunity_id','action_kind','basis'].every(k=>Object.hasOwn(c.properties,k))
      ||!Array.isArray(c.required)||c.required.length!==3||!['opportunity_id','action_kind','basis'].every(k=>c.required.includes(k))))return false;
  }
