    if(!/^c1266Literal[0-9]{1,3}$/.test(name))return false;
    const def=schema.$defs[name];
    if(idWire){
      const ordinal=/^c1266Literal(0|[1-9][0-9]{0,2})$/.exec(name);
      return ordinal!==null&&name==='c1266Literal'+ordinal[1]&&record(def)&&Object.keys(def).length===2
        &&Object.hasOwn(def,'type')&&Object.hasOwn(def,'enum')&&def.type==='string'
        &&Array.isArray(def.enum)&&def.enum.length>0&&def.enum.length<=200
        &&def.enum.every((id,index)=>id==='q'+ordinal[1]+'_'+index);
