async function bodyOf(req) {
  if (!req.body) throw Error('REQUEST_BODY_REQUIRED');
  const reader=req.body.getReader(),chunks=[];let total=0,timer;
  const expired=new Promise((_,reject)=>{timer=setTimeout(()=>{reader.cancel().catch(()=>{});reject(Error('REQUEST_TIMEOUT'));},10000);});
  try {
    for (;;) {const x=await Promise.race([reader.read(),expired]);if(x.done)break;total+=x.value.byteLength;
      if(total>8192){await reader.cancel();throw Error('REQUEST_TOO_LARGE');}chunks.push(x.value);}
  } finally {clearTimeout(timer);reader.releaseLock();}
  const joined=new Uint8Array(total);let at=0;for(const c of chunks){joined.set(c,at);at+=c.byteLength;}
  return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(joined));
}

// This adapter is created anew after getUser or a consumed server event receipt. It never trusts a user id, token,
// RPC name or scene in the request body. Finalize token stays in invocation memory.
export function createMissionDbAdapter({admin,userId,workerToken}) {
  if (!uuid(userId)||!admin?.rpc||typeof workerToken!=='string'||!workerToken) throw Error('MISSION_HTTP_CONFIG');
  const finalizers=new Map();
  async function rpc(name,args,{signal}={}) {
    const readOnly=name===RPC.asyncStatus||name==='mission_generic_director_narration_next_v1';
    let out;
    try{
      let pending=admin.rpc(name,args);
      if(signal&&typeof pending.abortSignal==='function')pending=pending.abortSignal(signal);
      out=await pending;
    }catch(error){if(readOnly)throw classifyMissionReadError(error);throw error;}
    if(out.error){
      if(readOnly)throw classifyMissionReadError(out.error,out.status);
      if(name===RPC.progress&&String(out.error.message??'').includes('MRS_V4_USE_STAFF_TICK'))
        throw Error('MISSION_STAFF_TICK_REQUIRED');
      if(name===RPC.staffTick&&['40001','P0001'].includes(out.error.code)&&out.error.message==='MGS_TICK_ACTOR_CONFLICT')throw Error('MGS_TICK_ACTOR_CONFLICT');
      const error=Error('MISSION_RPC_REJECTED');
      if(name==='mission_generic_provider_output_retain_v1'){
        error.retention_sqlstate=typeof out.error.code==='string'&&/^[0-9A-Z]{5}$/.test(out.error.code)?out.error.code:null;
        error.retention_code=['MGD_OUTPUT_RETAIN_INPUT','MGD_OUTPUT_RETAIN_AUTHORITY','MGD_OUTPUT_RETAIN_CONFLICT'].includes(out.error.message)?out.error.message:'UNCONFIRMED';
      }
      if(name==='mission_generic_retained_director_v1')error.retained_code=RETAINED_RPC_CODES.has(out.error.message)?out.error.message:'MISSION_RPC_REJECTED';
      throw error;
    }
    if(!object(out.data)){if(readOnly)throw missionReadError('invalid');throw Error('MISSION_RPC_REJECTED');}
    return out.data;
  }
  return {
    // p_user comes only from getUser or the service-validated event receipt, never the request body.
    d100Scope:(session,options)=>rpc(RPC.d100Scope,{p_session:session,p_user:userId},options),
    d100Pending:(session,options)=>rpc(RPC.d100Pending,{p_session:session},options),
    d100Consume:(session,receipt,hash,options)=>rpc(RPC.d100Consume,{p_session:session,p_receipt:receipt,p_source_sha256:hash},options),
    next:(session,options)=>rpc(RPC.next,{p_session:session,p_user:userId},options),
    progress:(session,request,options)=>rpc(RPC.progress,{p_session:session,p_user:userId,p_request:request},options),
    staffTick:(session,revision,options)=>rpc(RPC.staffTick,
      {p_session:session,p_user:userId,p_source_revision:revision,p_staff:userId},options),
    staffFinish:(body,options)=>rpc(RPC.staffFinish,{p_session:body.master_session_id,p_user:userId,p_source_revision:body.source_revision,p_expected_publication:body.expected_publication_id,p_request:body.request_key},options),
    claim:(request,options)=>rpc(RPC.claim,{p_user:userId,p_request:request},options),
    retainedDirector:(command,options)=>rpc('mission_generic_retained_director_v1',{p_user:userId,p_command:command},options),
    countedResume:(request,options)=>rpc('mission_generic_counted_resume_v1',{p_user:userId,p_request:request},options),
    readyResume:(request,proof,options)=>rpc('mission_generic_opening_ready_resume_v1',{p_user:userId,p_request:request,p_proof:proof},options),
    claimResume:(request,proof,options)=>rpc('mission_generic_opening_claim_resume_v1',{p_user:userId,p_request:request,p_proof:proof},options),
    reject:(request,lease,code,options)=>rpc(RPC.reject,{p_user:userId,p_request:request,p_lease:lease,p_code:code},options),
    status:(request,options)=>rpc(RPC.status,{p_user:userId,p_request:request},options),
    asyncStatus:(request,options)=>rpc(RPC.asyncStatus,{p_user:userId,p_request:request},options),
    authorize:(work,policy,options)=>rpc(RPC.authorize,{p_work:work.work_id,p_lease:work.lease_id,p_worker_token:workerToken,p_policy:policy},options),
    directorNarrationNext:(parentRequest,parentReceipt,options)=>rpc('mission_generic_director_narration_next_v1',
      {p_user:userId,p_request:parentRequest,p_parent_receipt:parentReceipt},options),
    countStart:(work,payloadText,payloadSha,options)=>rpc('mission_generic_input_count_start_v1',
      {p_work:work.work_id,p_lease:work.lease_id,p_payload_text:payloadText,p_payload_sha:payloadSha},options),
    countFinish:(work,measurement,status,response,options)=>rpc('mission_generic_input_count_finish_v1',
      {p_work:work.work_id,p_lease:work.lease_id,p_measurement:measurement,p_status:status,p_response:response},options),
    consume:async(work,permission,options)=>{
      const r=await rpc(RPC.consume,{p_work:work.work_id,p_lease:work.lease_id,p_worker_token:workerToken,
        p_authorization:permission.authorization_id,p_dispatch_token:permission.dispatch_token},options);
      if(typeof r.finalize_token!=='string'||!r.finalize_token)throw Error('MISSION_CONSUME_RECEIPT');
      finalizers.set(work.work_id,r.finalize_token);
      const {finalize_token,...publicReceipt}=r;return publicReceipt;
    },
    markSent:(work,dispatch,options)=>rpc(RPC.markSent,
      {p_work:work.work_id,p_dispatch:dispatch.dispatch_id},options),
    retainOutput:(work,dispatch,artifact,options)=>{
      const token=finalizers.get(work.work_id);if(!token)throw Error('MISSION_FINALIZE_TOKEN_MISSING');
      return rpc('mission_generic_provider_output_retain_v1',{p_work:work.work_id,p_finalize_token:token,
        p_raw_output:artifact.raw_output,p_raw_sha256:artifact.raw_sha256,p_provider_status:artifact.status,
        p_provider_response_id:artifact.response_id,p_provider_request_id:artifact.request_id,p_usage:artifact.metrics},options);
    },
    finalize:(work,result,hash,options)=>{
      const token=finalizers.get(work.work_id);if(!token)throw Error('MISSION_FINALIZE_TOKEN_MISSING');
      return rpc(RPC.finalize,{p_work:work.work_id,p_finalize_token:token,p_result_text:canonical(result),p_result_sha:hash},options);
    },
    cachedPublication:(session,work,options)=>rpc(RPC.cachedPublication,
      {p_session:session,p_work:work,p_staff:userId},options),
  };
}


