const d100Schema='mission-generic-d100-wakeup/1';
const sha256=x=>typeof x==='string'&&/^[0-9a-f]{64}$/.test(x);
const revision=x=>Number.isSafeInteger(x)&&x>0;
const stepKey=x=>typeof x==='string'&&/^[a-z][a-z0-9_]{0,63}$/.test(x);
function d100Public(session,state,code=null) {
  return {schema_version:d100Schema,master_session_id:session,state,progress:{code},retry:false,provider_retry_allowed:false};
