function d100ScopeValid(x,session) {
  return exact(x,['schema_version','session_id','source_sha256','run_control_version','step_key','operation'])
    &&x.schema_version==='quest-d100-wakeup-scope/1'&&x.session_id===session
    &&sha256(x.source_sha256)&&revision(x.run_control_version)&&stepKey(x.step_key)
    &&x.operation==='discover_pending_before_claim';
}
function d100PendingValid(x,scope) {
  return exact(x,['schema_version','session_id','receipts'])&&x.schema_version==='quest-d100-pending/1'
    &&x.session_id===scope.session_id&&Array.isArray(x.receipts)&&x.receipts.length<=1
    &&x.receipts.every(r=>exact(r,['receipt_id','source_sha256','binding_id','run_control_version'])
      &&uuid(r.receipt_id)&&sha256(r.source_sha256)&&uuid(r.binding_id)
      &&r.run_control_version===scope.run_control_version);
}
function d100ConsumedValid(x,receipt) {
  return exact(x,['step','run_control_version','event_id','context_fingerprint','authority_receipt_id','trigger_key'])
    &&stepKey(x.step)&&x.run_control_version===receipt.run_control_version+1
    &&uuid(x.event_id)&&sha256(x.context_fingerprint)&&uuid(x.authority_receipt_id)
    &&typeof x.trigger_key==='string'&&/^[a-z][a-z0-9_]{0,63}$/.test(x.trigger_key);
}

// Public untrusted wake hints and authenticated recovery commands carry no game authority. Each invocation consumes
// one durable event and executes at most one canonical Native work.
const EVENT_WAKE_FIELDS=['schema_version','event_key','event_version'];
const EVENT_CLAIM_FIELDS=['schema_version','event_key','event_version','status','claim_id','master_session_id','principal_user','mode','scope_location','expires_at'];
const EVENT_ACK_FIELDS=['schema_version','event_key','event_version','status'];
const EVENT_NEXT_FIELDS=['schema_version','event_key','event_version','claim_id','master_session_id','state','request','native_claim'];
const EVENT_SETTLE_FIELDS=['schema_version','event_key','event_version','claim_id','master_session_id','state'];
const EVENT_STAFF_LOCATION='0b85f354-9cdb-47e1-baf9-3d266bb7e06b';
function eventWakeValid(wake){
 return exact(wake,EVENT_WAKE_FIELDS)&&wake.schema_version==='mission-event-wake/2'
  &&uuid(wake.event_key)&&revision(wake.event_version);
}
function eventProofValid(proof){
 return exact(proof,['schema_version'])&&proof.schema_version==='mission-event-wake-proof/2'
  ||exact(proof,['schema_version','authenticated_user','request_key'])&&proof.schema_version==='mission-event-recovery-proof/1'
   &&uuid(proof.authenticated_user)&&uuid(proof.request_key);
}
function scheduleServerEvent(event,proof,{admin,provider,workerToken,waitUntil,started}){
 if(!eventProofValid(proof)||typeof waitUntil!=='function')return false;
 let release;
 const scheduled=new Promise(resolve=>{release=resolve;})
  .then(()=>runServerEvent(event,{admin,provider,workerToken,started,proof}))
  .catch(()=>{console.warn('mission_server_event_dispatch_unconfirmed');});
 // Registration precedes even the event claim, not only provider HTTP.
 try{waitUntil(scheduled);}catch{return false;}
 release();return true;
}
function serverRecoveryCommandValid(mode,command,session){
 if(mode==='retained_director')return exact(command,['schema_version','mode','master_session_id','work_id'])
  &&command.schema_version==='mission-retained-director-recovery/1'&&command.mode==='prepare'
  &&command.master_session_id===session&&uuid(command.work_id);
 if(mode==='cached_publication')return exact(command,['schema_version','master_session_id','work_id'])
  &&command.schema_version==='mission-generic-staff-cached-publication/1'
  &&command.master_session_id===session&&uuid(command.work_id);
 return false;
}
function serverRetainedReplyValid(r,body){
 return exact(r,['schema_version','status','master_session_id','work_id','child_request','child_work_id','replayed'])
  &&r.schema_version===body.schema_version&&['ready','observing','published','failed'].includes(r.status)
  &&r.master_session_id===body.master_session_id&&r.work_id===body.work_id&&typeof r.replayed==='boolean'
  &&(r.child_request===null&&r.child_work_id===null&&r.status==='failed'
   ||uuid(r.child_work_id)&&r.child_work_id!==body.work_id&&validateRequest(r.child_request)&&r.child_request.master_session_id===body.master_session_id);
}
function serverCachedReplyValid(r,body){
 if(r?.schema_version!=='mission-generic-staff-cached-publication/1'
  ||!['published','failed','not_applicable','recovered'].includes(r.status))return false;
 if(r.status==='recovered'&&(!exact(r,['schema_version','status','master_session_id','work_id','replayed'])
  ||r.master_session_id!==body.master_session_id||!uuid(r.work_id)||r.work_id===body.work_id
  ||typeof r.replayed!=='boolean'))return false;
 return true;
}
