function sanitizeEventRpcDiagnostic(name,sqlstate,guard){
 return {rpc_name:EVENT_RPC_DIAGNOSTIC_NAMES.includes(name)?name:null,
  sqlstate:typeof sqlstate==='string'&&/^[0-9A-Z]{5}$/.test(sqlstate)?sqlstate:null,
  guard_code:typeof guard==='string'&&EVENT_RPC_GUARD_CODES.has(guard)?guard:null};
}
function eventRpcDiagnosticError(name,raw){
 const failure=Error('MISSION_EVENT_WAKE_UNCONFIRMED');
 const guard=typeof raw?.message==='string'&&EVENT_RPC_GUARD_CODES.has(raw.message)?raw.message:
  typeof raw?.code==='string'&&EVENT_RPC_GUARD_CODES.has(raw.code)?raw.code:null;
 failure.eventRpcDiagnostic=sanitizeEventRpcDiagnostic(name,raw?.code,guard);
 return failure;
}
function eventRpcDiagnosticLog(error,wake){
 const d=error?.eventRpcDiagnostic;
 return {event_key:uuid(wake?.event_key)?wake.event_key:null,
  ...sanitizeEventRpcDiagnostic(d?.rpc_name,d?.sqlstate,d?.guard_code)};
}
async function runServerEvent(wake,{admin,provider,workerToken,started,proof}){
 let eventDeadline=started+380000,executionDeadline=eventDeadline-10000;
 async function eventRpc(name,args,cleanup=false){
  const remaining=(cleanup?eventDeadline:executionDeadline)-performance.now();
  if(remaining<=0)throw Error('MISSION_EVENT_WAKE_TIMEOUT');
  const ctl=new AbortController();let timer;
  try{
   const call=Promise.resolve().then(()=>{
    let pending=admin.rpc(name,args);
    if(typeof pending?.abortSignal==='function')pending=pending.abortSignal(ctl.signal);
    return pending;
   });
   const out=await Promise.race([call,new Promise((_,reject)=>{
    const rpcTimeoutMs=name==='mission_generic_event_next_v1'?25000:8000;
    timer=setTimeout(()=>{ctl.abort();reject(Error('MISSION_EVENT_WAKE_TIMEOUT'));},Math.min(rpcTimeoutMs,remaining));
   })]);
   if(out?.error||!object(out?.data))throw eventRpcDiagnosticError(name,out?.error);
   return out.data;
  }catch(error){
   if(error?.eventRpcDiagnostic)throw error;
   throw eventRpcDiagnosticError(name,error);
  }finally{clearTimeout(timer);}
 }
 let claim;
 try{claim=await eventRpc('mission_generic_event_claim_v1',{
  p_event_key:wake.event_key,p_event_version:wake.event_version,p_proof:proof});}
 catch{console.warn('mission_server_event_claim_unconfirmed');return;}
 const sameEvent=x=>x?.event_key===wake.event_key&&x?.event_version===wake.event_version;
 if(exact(claim,EVENT_ACK_FIELDS)&&claim.schema_version==='mission-event-claim/1'
   &&sameEvent(claim)&&['busy','terminal'].includes(claim.status))return;
 if(!exact(claim,EVENT_CLAIM_FIELDS)||claim.schema_version!=='mission-event-claim/1'
   ||!sameEvent(claim)||claim.status!=='claimed'||!uuid(claim.claim_id)
   ||!uuid(claim.master_session_id)||!uuid(claim.principal_user)
   ||claim.mode!=='staff_simulation'||claim.scope_location!==EVENT_STAFF_LOCATION
   ||typeof claim.expires_at!=='string'||!Number.isFinite(Date.parse(claim.expires_at))){
  console.warn('mission_server_event_claim_invalid');return;
 }
 let phase='next',request=null,receipt=null,status='uncertain';
 try{
  const next=await eventRpc('mission_generic_event_next_v1',{
   p_event_key:wake.event_key,p_event_version:wake.event_version,p_claim_id:claim.claim_id});
  if(!exact(next,EVENT_NEXT_FIELDS)||next.schema_version!=='mission-event-next/1'
    ||!sameEvent(next)||next.claim_id!==claim.claim_id||next.master_session_id!==claim.master_session_id
    ||!['dispatch','waiting','terminal','uncertain'].includes(next.state)
    ||(next.state==='dispatch'?(!validateRequest(next.request)||next.request.master_session_id!==claim.master_session_id
      ||!exact(next.native_claim,['mode','body'])||!['normal','counted_resume','retained_director','cached_publication'].includes(next.native_claim.mode)
      ||(['normal','counted_resume'].includes(next.native_claim.mode)
       ?(!exact(next.native_claim.body,next.native_claim.mode==='counted_resume'?['state','granted_now','work','count_reuse']:['state','granted_now','work'])
        ||next.native_claim.body.state!=='claimed'||next.native_claim.body.granted_now!==true||!object(next.native_claim.body.work))
       :!serverRecoveryCommandValid(next.native_claim.mode,next.native_claim.body,claim.master_session_id)))
     :(next.request!==null||next.native_claim!==null)))
   throw Error('MISSION_EVENT_NEXT_INVALID');
  if(next.state!=='dispatch'){
   status=next.state==='uncertain'?'uncertain':'complete';return;
  }
  request=next.request;
  // Only the consumed server receipt supplies this continuation principal.
  // The inbound wake contains no user id, request tuple or provider options.
  const baseDb=createMissionDbAdapter({admin,userId:claim.principal_user,workerToken});
  const mode=next.native_claim.mode,command=next.native_claim.body;
   if(mode==='normal'&&directorOutput32(command.work)&&command.work.limits?.max_output_tokens===32000&&command.work.limits.provider_timeout_ms===330000){
    eventDeadline=started+390000;executionDeadline=eventDeadline-10000;
   } // Exact server-owned successor only; still below the paid Edge 400s wall limit.
  async function paidCall(operation){
   const remaining=Math.floor(Math.min(30000,executionDeadline-performance.now()));
   if(remaining<=0)throw Error('MISSION_EVENT_WAKE_TIMEOUT');
   return operation({signal:AbortSignal.timeout(remaining)});
  }
  if(mode==='retained_director'){
   phase='run';
   let recovered=await paidCall(options=>baseDb.retainedDirector(command,options));
   if(recovered?.schema_version==='mission-retained-director-source/1'){
    if(!validateRequest(recovered.proof?.request)||canonical(recovered.proof.request)!==canonical(request))
     throw Error('MISSION_EVENT_RETAINED_REQUEST_DRIFT');
    const normalized_result=await normalizeRetainedDirector(recovered,{
     user:claim.principal_user,session:command.master_session_id,work:command.work_id});
    recovered=await paidCall(options=>baseDb.retainedDirector({...command,mode:'apply',
     prepare_receipt_id:recovered.proof.prepare_receipt_id,prepare_sha256:recovered.proof.prepare_sha256,normalized_result},options));
   }
   if(!serverRetainedReplyValid(recovered,command))throw Error('MISSION_EVENT_RETAINED_REPLY_INVALID');
   status=recovered.status==='failed'?'failed':'complete';return;
  }
  if(mode==='cached_publication'){
   phase='run';
   const recovered=await paidCall(options=>baseDb.cachedPublication(command.master_session_id,command.work_id,options));
   if(!serverCachedReplyValid(recovered,command))throw Error('MISSION_EVENT_CACHED_REPLY_INVALID');
   status=['published','recovered'].includes(recovered.status)?'complete':recovered.status==='failed'?'failed':'uncertain';return;
  }
  let handedOff=false;
  const db={...baseDb,claim:async candidate=>{
   if(handedOff||candidate!==request)throw Error('MISSION_EVENT_NATIVE_HANDOFF_INVALID');
   handedOff=true;return next.native_claim.body;
  }};
  // Native claim was granted in event_next's transaction under its private
  // event permit. Hand over that exact receipt once; never claim in a new RPC.
  phase='prepare';
  const prepared=await prepareMissionEvent({request,db,provider,executionDeadline,
   countedResume:next.native_claim.mode==='counted_resume'});
  if(prepared===null)return;
  phase='run';
  const result=await runMissionEvent({request,db,provider,prepared});
  receipt=uuid(result?.receipt_id)?result.receipt_id:null;
  if(result?.status===200&&receipt!==null&&['MISSION_EVENT_COMPLETE','MISSION_EVENT_FAILED'].includes(result.code))
   status=result.code==='MISSION_EVENT_COMPLETE'?'complete':'failed';
 }catch(error){console.warn('mission_server_event_execution_unconfirmed',eventRpcDiagnosticLog(error,wake));}
 finally{
  // Diagnostic outcome is never publication authority. The service RPC reads
  // Native work/receipt state and owns any distinct successor event+wakeup.
  try{
   const settled=await eventRpc('mission_generic_event_settle_v1',{
    p_event_key:wake.event_key,p_event_version:wake.event_version,p_claim_id:claim.claim_id,
    p_outcome:{phase,status,request,receipt_id:receipt}},true);
   if(!exact(settled,EVENT_SETTLE_FIELDS)||settled.schema_version!=='mission-event-settle/1'
     ||!sameEvent(settled)||settled.claim_id!==claim.claim_id||settled.master_session_id!==claim.master_session_id
     ||!['waiting','terminal','uncertain','successor_queued'].includes(settled.state))
    throw Error('MISSION_EVENT_SETTLE_INVALID');
  }catch{console.warn('mission_server_event_settle_unconfirmed');}
 }
}

export async function handleMissionGeneric(req,{admin,provider,workerToken,waitUntil,allowedOrigins=['https://theuntoldstory.it','https://www.theuntoldstory.it']}={}) {
  const eventStarted=performance.now();
  const origin=req.headers.get('origin');
  const headers={'content-type':'application/json','cache-control':'no-store','vary':'Origin'};
  const respond=(x,status=200)=>new Response(JSON.stringify(x),{status,headers});
  if(origin&&!allowedOrigins.includes(origin))return respond({code:'ORIGIN_FORBIDDEN'},403);
  if(origin){headers['access-control-allow-origin']=origin;headers['access-control-allow-headers']='authorization,apikey,content-type,x-client-info';headers['access-control-allow-methods']='POST,OPTIONS';}
  if(req.method==='OPTIONS')return new Response(null,{status:204,headers});
  if(req.method!=='POST')return respond({code:'METHOD_NOT_ALLOWED'},405);
  if(!admin?.auth?.getUser||!admin?.rpc||!provider?.create||typeof workerToken!=='string'||!workerToken)
    return respond({code:'MISSION_ADAPTER_UNAVAILABLE'},503);
  const eventMode=req.headers.get('x-tus-server-event');
  if(eventMode!==null){
    if(eventMode!=='event42'||origin)return respond({code:'MISSION_EVENT_WAKE_FORBIDDEN'},403);
    if(typeof waitUntil!=='function')return respond({code:'MISSION_ASYNC_UNAVAILABLE'},503);
    let wake;try{wake=await bodyOf(req);}catch{return respond({code:'REQUEST_INVALID'},400);}
    if(!eventWakeValid(wake))return respond({code:'REQUEST_INVALID'},400);
    const proof={schema_version:'mission-event-wake-proof/2'};
    if(!scheduleServerEvent(wake,proof,{admin,provider,workerToken,waitUntil,started:eventStarted}))
      return respond({code:'MISSION_ASYNC_UNAVAILABLE'},503);
    return respond({schema_version:'mission-event-wake-ack/1',status:'accepted',retry:false},202);
  }
  const authorization=req.headers.get('authorization')??'';
  if(!/^Bearer\s+\S+$/i.test(authorization))return respond({code:'UNAUTHORIZED'},401);
  let user,body;
  try {const r=await admin.auth.getUser(authorization.replace(/^Bearer\s+/i,''));if(r.error||!uuid(r.data?.user?.id))throw Error('AUTH');user=r.data.user.id;}
  catch{return respond({code:'UNAUTHORIZED'},401);}
  try{body=await bodyOf(req);}catch{return respond({code:'REQUEST_INVALID'},400);}
  if(body?.schema_version==='mission-event-recovery/1'){
    if(!exact(body,['schema_version','event_key','event_version','request_key'])
      ||!uuid(body.event_key)||!revision(body.event_version)||!uuid(body.request_key))
      return respond({code:'REQUEST_INVALID'},400);
    // authenticated_user is compiled exclusively from the verified getUser
    // result. The browser cannot supply a continuation principal or proof.
    const proof={schema_version:'mission-event-recovery-proof/1',authenticated_user:user,request_key:body.request_key};
    if(!scheduleServerEvent(body,proof,{admin,provider,workerToken,waitUntil,started:eventStarted}))
      return respond({code:'MISSION_ASYNC_UNAVAILABLE'},503);
    return respond({schema_version:'mission-event-wake-ack/1',status:'accepted',retry:false},202);
  }
  let db;try{db=createMissionDbAdapter({admin,userId:user,workerToken});}catch{return respond({code:'MISSION_ADAPTER_UNAVAILABLE'},503);}
  // Paid retained output stays service-only. Client cannot supply normalized data or apply authority.
  if(body?.schema_version==='mission-retained-director-recovery/1'){
    if(!exact(body,['schema_version','mode','master_session_id','work_id'])||!['prepare','read'].includes(body.mode)
      ||!uuid(body.master_session_id)||!uuid(body.work_id))return respond({code:'REQUEST_INVALID'},400);
    const validReply=r=>exact(r,['schema_version','status','master_session_id','work_id','child_request','child_work_id','replayed'])
      &&r.schema_version===body.schema_version&&['ready','observing','published','failed'].includes(r.status)
      &&r.master_session_id===body.master_session_id&&r.work_id===body.work_id&&typeof r.replayed==='boolean'
      &&(r.child_request===null&&r.child_work_id===null&&r.status==='failed'
       ||uuid(r.child_work_id)&&r.child_work_id!==body.work_id&&validateRequest(r.child_request)&&r.child_request.master_session_id===body.master_session_id);
    let phase='prepare';
    try{
      let result=await db.retainedDirector(body,{signal:AbortSignal.timeout(30000)});
      if(result?.schema_version==='mission-retained-director-source/1'&&body.mode==='prepare'){
        const normalized_result=await normalizeRetainedDirector(result,{user,session:body.master_session_id,work:body.work_id},name=>{phase=RETAINED_PHASES.has(name)?name:'normalizer_unknown';});
        phase='apply';
        result=await db.retainedDirector({...body,mode:'apply',prepare_receipt_id:result.proof.prepare_receipt_id,
          prepare_sha256:result.proof.prepare_sha256,normalized_result},{signal:AbortSignal.timeout(30000)});
      }
      phase='reply';if(!validReply(result))throw Error('MISSION_RETAINED_REPLY_INVALID');
      return respond(result);
    }catch(error){
      const original=typeof error?.retained_code==='string'?error.retained_code:error?.message;
      const reason_code=RETAINED_CODES.has(original)?original:original==='scene_noncanonical_value'?'MISSION_RETAINED_CANONICAL_INVALID'
        :error?.name==='TypeError'?'MISSION_RETAINED_TYPE_ERROR':error?.name==='SyntaxError'?'MISSION_RETAINED_SYNTAX_ERROR':'MISSION_RETAINED_UNCLASSIFIED';
      console.info('mission_retained_recovery_diagnostic',{work_id:body.work_id,phase,reason_code});
      return respond({code:'MISSION_RETAINED_RECOVERY_UNCONFIRMED',phase,reason_code},409);
    }
  }
  // Explicit protected simulation closure. This route never starts provider work.
  if(body?.schema_version==='mission-generic-staff-finish/1'){
    if(!exact(body,['schema_version','master_session_id','source_revision','expected_publication_id','request_key'])
      ||!uuid(body.master_session_id)||!sha256(body.source_revision)||!uuid(body.expected_publication_id)||!uuid(body.request_key))return respond({code:'REQUEST_INVALID'},400);
    try{
      const result=await db.staffFinish(body);
      if(!exact(result,['schema_version','master_session_id','state','source_revision','publication_id','request_key','outcome','receipt_sha256','replayed'])
        ||result.schema_version!=='mission-generic-staff-finish-result/1'||result.state!=='closed'||result.outcome!=='success'
        ||result.master_session_id!==body.master_session_id||result.source_revision!==body.source_revision
        ||result.publication_id!==body.expected_publication_id||result.request_key!==body.request_key
        ||!sha256(result.receipt_sha256)||typeof result.replayed!=='boolean')return respond({code:'MISSION_STAFF_FINISH_INVALID'},503);
      return respond(result);
    }catch{return respond({code:'MISSION_STAFF_FINISH_REJECTED'},409);}
  }
  // Read-only recovery never calls progress, claim, Count or Generation. `none` permits no resend.
  if(body?.schema_version==='mission-generic-async-recover/1'){
    const selector=body.selector;
    const requestSelector=exact(selector,['kind','request'])&&selector.kind==='request'
      &&validateRequest(selector.request)&&selector.request.master_session_id===body.master_session_id;
    const tickSelector=exact(selector,['kind','source_revision'])&&selector.kind==='staff_tick'&&sha256(selector.source_revision);
    const nativeSelector=exact(selector,['kind','request_key'])&&selector.kind==='native_tick'&&uuid(selector.request_key);
    if(!exact(body,['schema_version','master_session_id','selector'])||!uuid(body.master_session_id)
      ||!requestSelector&&!tickSelector&&!nativeSelector)return respond({code:'REQUEST_INVALID'},400);
    try{
      const s=await db.asyncStatus(body),keys=['schema_version','status','request','work_id','state','receipt_id','result_sha256','kind','retry','provider_retry_allowed'];
      if(!exact(s,keys)||s.schema_version!=='mission-generic-async-recovery/1'||!['owned','none','no_work'].includes(s.status)
        ||s.retry!==false||s.provider_retry_allowed!==false)throw Error('recovery_shape');
      if(s.status==='none'||s.status==='no_work'){
        if(s.status==='no_work'&&!tickSelector&&!nativeSelector||['request','work_id','state','receipt_id','result_sha256','kind'].some(k=>s[k]!==null))throw Error('recovery_none');
      }else if(!validateRequest(s.request)||s.request.master_session_id!==body.master_session_id||!uuid(s.work_id)
        ||!['ready','claimed','authorized','provider_started','uncertain','completed','failed'].includes(s.state)
        ||!['director','narration','choice'].includes(s.kind)
        ||!(s.receipt_id===null||uuid(s.receipt_id))||!(s.result_sha256===null||sha256(s.result_sha256))
        ||s.state==='completed'&&(!uuid(s.receipt_id)||!sha256(s.result_sha256))
        ||requestSelector&&canonical(s.request)!==canonical(selector.request))throw Error('recovery_owned');
      return respond(s);
    }catch(error){const failure=missionReadFailureResponse(error,'MISSION_ASYNC_RECOVERY');return respond(failure.body,failure.status);}
  }
  // Status cannot claim a lease, mutate a role or initiate Count/Generation.
  if(exact(body,['schema_version','request'])&&body.schema_version==='mission-generic-async-status/1'){
    if(!validateRequest(body.request))return respond({code:'REQUEST_INVALID'},400);
    try {
      const s=await db.asyncStatus(body.request);
      if(s?.schema_version!=='mission-generic-status/1'||!uuid(s.work_id)||s.master_session_id!==body.request.master_session_id
        ||s.event_id!==body.request.event_id||s.request_key!==body.request.request_key||s.revision!==body.request.expected_revision
        ||!['ready','claimed','authorized','provider_started','uncertain','completed','failed'].includes(s.state))
        throw missionReadError('invalid');
      return respond({schema_version:'mission-generic-async-status-response/1',work_id:s.work_id,master_session_id:s.master_session_id,
        event_id:s.event_id,request_key:s.request_key,revision:s.revision,state:s.state,
        receipt_id:uuid(s.receipt_id)?s.receipt_id:null,result_sha256:sha256(s.result_sha256)?s.result_sha256:null,
        retry:false,provider_retry_allowed:false});
    }catch(error){const failure=missionReadFailureResponse(error,'MISSION_ASYNC_STATUS');return respond(failure.body,failure.status);}
  }
  async function deliveryFor(request,dispatchDb=db,countedResume=false){
    if(typeof waitUntil!=='function')return {status:503,code:'MISSION_ASYNC_UNAVAILABLE',retry:false,provider_retry_allowed:false};
    let prepared;
    try{prepared=await prepareMissionEvent({request,db:dispatchDb,provider,countedResume});}
    catch{return {status:202,code:'MISSION_EVENT_UNCERTAIN',phase:'claim',retry:false,provider_retry_allowed:false};}
    if(prepared===null){
      try{
        const s=await dispatchDb.status(request); // Preserve the existing terminal replay path; readonly observers use asyncStatus separately.
        if(s?.schema_version==='mission-generic-status/1'&&s.master_session_id===request.master_session_id
          &&s.event_id===request.event_id&&s.request_key===request.request_key&&s.revision===request.expected_revision
          &&['completed','failed'].includes(s.state)&&uuid(s.receipt_id))
          return {status:200,code:s.state==='completed'?'MISSION_EVENT_COMPLETE':'MISSION_EVENT_FAILED',receipt_id:s.receipt_id,
            replay:true,retry:false,provider_retry_allowed:false};
      }catch{/* An unknown acknowledgement authorizes no retry. */}
      return {status:202,code:'MISSION_EVENT_UNCERTAIN',phase:'existing_work',retry:false,provider_retry_allowed:false};
    }
    // Unrelated legacy consumers keep their synchronous contract, using the same persisted claim.
    if(!missionEventAsyncReady(prepared))return runMissionEvent({request,db:dispatchDb,provider,prepared});
    // Register before releasing the provider continuation. Registration failure cannot send provider HTTP.
    let release;
    const scheduled=new Promise(resolve=>{release=resolve;}).then(()=>runMissionEvent({request,db:dispatchDb,provider,prepared}))
      .then(result=>{
        if(result?.status===202){
          const phase=['claim','validation','pre_provider_failure','count_reuse_validation','count_reuse_request_changed','input_count_start','input_count_finish','input_count_overflow','input_count_unknown','authorization','provider','finalize'].includes(result.phase)?result.phase:'unclassified';
          console.info('mission_async_worker_result',{work_id:uuid(prepared.work_id)?prepared.work_id:null,phase,
            code:result.code==='MISSION_EVENT_UNCERTAIN'?'MISSION_EVENT_UNCERTAIN':'MISSION_WORKER_RESULT_UNCLASSIFIED'});
        }
        return result;
      })
      .catch(()=>{console.warn('mission_async_dispatch_unconfirmed');});
    try{waitUntil(scheduled);}catch{return {status:503,code:'MISSION_ASYNC_UNAVAILABLE',retry:false,provider_retry_allowed:false};}
    release();
    return {status:202,code:'MISSION_EVENT_PENDING',schema_version:'mission-generic-pending/1',
      ...prepared,retry:false,provider_retry_allowed:false};
  }
  // Explicit continuation of an already counted request. No progress/start/Count.
  if(body?.schema_version==='mission-generic-counted-resume-request/1'){
    if(!exact(body,['schema_version','request'])||!validateRequest(body.request))
      return respond({code:'REQUEST_INVALID',retry:false,provider_retry_allowed:false},400);
    const countedDb={...db,
      claim:(request,options)=>db.countedResume(request,options),
      status:(request,options)=>db.asyncStatus(request,options)};
    const delivery=await deliveryFor(body.request,countedDb,true);
    return respond(delivery,delivery.status);
  }
  // Explicit same-opening request. Eligibility is not a grant: the atomic RPC rechecks it.
  if(body?.schema_version==='mission-opening-ready-resume-request/1'){
    const p=body.proof,q=body.request;
    const keys=['schema_version','eligible_to_request','master_session_id','work_id','event_id','request_key','expected_revision','payload_sha256','binding_sha256','release_sha256','source_qualification_sha256','denial_audit_id','proof_sha256'];
    if(!exact(body,['schema_version','request','proof'])||!validateRequest(q)||!exact(p,keys)
      ||p.schema_version!=='mission-opening-ready-resume/1'||p.eligible_to_request!==true
      ||!['master_session_id','work_id','event_id','request_key'].every(k=>uuid(p[k]))
      ||!revision(p.expected_revision)||!['payload_sha256','binding_sha256','release_sha256','source_qualification_sha256','proof_sha256'].every(k=>sha256(p[k]))
      ||typeof p.denial_audit_id!=='string'||! /^[1-9][0-9]*$/.test(p.denial_audit_id)
      ||p.master_session_id!==q.master_session_id||p.event_id!==q.event_id||p.request_key!==q.request_key||p.expected_revision!==q.expected_revision)
      return respond({code:'REQUEST_INVALID',retry:false,provider_retry_allowed:false},400);
    // One adapter object and the original request object survive prepare/run's WeakMap binding.
    const resumeDb={...db,claim:(request,options)=>db.readyResume(request,p,options)};
    const delivery=await deliveryFor(q,resumeDb);
    return respond(delivery,delivery.status);
  }
  // Explicit same-claimed-opening recovery. Eligibility is not a grant: the atomic RPC rechecks it.
  if(body?.schema_version==='mission-opening-claim-resume-request/1'){
    const p=body.proof,q=body.request;
    const keys=['schema_version','eligible_to_request','master_session_id','work_id','event_id','request_key','expected_revision','payload_sha256','binding_sha256','release_sha256','source_qualification_sha256','previous_lease_id','dispatch_receipt_id','contract_sha256','contract_release_sha256','resume_audit_id','proof_sha256'];
    if(!exact(body,['schema_version','request','proof'])||!validateRequest(q)||!exact(p,keys)
      ||p.schema_version!=='mission-opening-claim-resume/1'||p.eligible_to_request!==true
      ||!['master_session_id','work_id','event_id','request_key','previous_lease_id','dispatch_receipt_id'].every(k=>uuid(p[k]))
      ||!revision(p.expected_revision)||!['payload_sha256','binding_sha256','release_sha256','source_qualification_sha256','contract_sha256','contract_release_sha256','proof_sha256'].every(k=>sha256(p[k]))
      ||typeof p.resume_audit_id!=='string'||! /^[1-9][0-9]*$/.test(p.resume_audit_id)
      ||p.master_session_id!==q.master_session_id||p.event_id!==q.event_id||p.request_key!==q.request_key||p.expected_revision!==q.expected_revision)
      return respond({code:'REQUEST_INVALID',retry:false,provider_retry_allowed:false},400);
    // One adapter object and the original request object survive prepare/run's WeakMap binding.
    const resumeDb={...db,claim:(request,options)=>db.claimResume(request,p,options)};
    const delivery=await deliveryFor(q,resumeDb);
    return respond(delivery,delivery.status);
  }
  // C1266 technical observation: authenticated STATUS only, never claim/Count/Gen.
  if(body?.schema_version==='mission-generic-count-status/1'){
    const keys=['schema_version','work_id','master_session_id','event_id','request_key','expected_revision',
      'dispatch_receipt_id','measurement_id','generation_request_sha256','policy_snapshot_sha256','release_sha256','failure_code'];
    if(!exact(body,keys)||!['work_id','master_session_id','event_id','request_key','dispatch_receipt_id','measurement_id'].every(k=>uuid(body[k]))
      ||!revision(body.expected_revision)||!['generation_request_sha256','policy_snapshot_sha256','release_sha256'].every(k=>sha256(body[k]))
      ||!['MISSION_INPUT_COUNT_UNKNOWN','MISSION_INPUT_COUNT_OVERFLOW'].includes(body.failure_code))
      return respond({code:'REQUEST_INVALID',retry:false,provider_retry_allowed:false},400);
    let status;
    try{status=await db.status(body);}catch{return respond({code:'MISSION_COUNT_STATUS_UNCONFIRMED',retry:false,provider_retry_allowed:false},503);}
    if(!exact(status,['schema_version','work_id','master_session_id','event_id','request_key','revision','state','receipt_id','result_sha256'])
      ||status.schema_version!=='mission-generic-status/1'||status.state!=='failed'||!uuid(status.receipt_id)||!sha256(status.result_sha256)
      ||status.work_id!==body.work_id||status.master_session_id!==body.master_session_id||status.event_id!==body.event_id
      ||status.request_key!==body.request_key||status.revision!==body.expected_revision)
      return respond({code:'MISSION_COUNT_STATUS_UNCONFIRMED',retry:false,provider_retry_allowed:false},503);
    return respond({schema_version:'mission-generic-count-status-response/1',master_session_id:status.master_session_id,
      work_id:status.work_id,event_id:status.event_id,request_key:status.request_key,revision:status.revision,
      receipt_id:status.receipt_id,result_sha256:status.result_sha256,state:'failed',retry:false,provider_retry_allowed:false});
  }
  const narrationRead=await directorNarrationRead(body,db);
  if(narrationRead.handled)return respond(narrationRead.body,narrationRead.status);

  if(exact(body,['schema_version','master_session_id'])&&body.schema_version===d100Schema&&uuid(body.master_session_id)){
    const session=body.master_session_id;
    let scope,pendingWork;
    // Discovery precedes next/claim even when there is no pre-existing narration work.
    try {scope=await db.d100Scope(session);}catch{return respond(d100Public(session,'rejected'),403);}
    if(!d100ScopeValid(scope,session))return respond(d100Public(session,'uncertain'),503);
    try {pendingWork=await db.d100Pending(session);}catch{return respond(d100Public(session,'uncertain'),503);}
    if(!d100PendingValid(pendingWork,scope))return respond(d100Public(session,'uncertain'),503);
    for(const receipt of pendingWork.receipts){
      // A lost acknowledgement is uncertain: no second consume, roll, route or provider retry in this invocation.
      let consumed;
      try {consumed=await db.d100Consume(session,receipt.receipt_id,receipt.source_sha256);}
      catch{return respond(d100Public(session,'uncertain'),503);}
