    || l.max_request_bytes < l.max_input_bytes || !positive(l.transport_max_chars) || l.transport_max_chars > 5000
    || !positive(l.provider_timeout_ms) || l.provider_timeout_ms > (['mission-generic-provider-input/4','mission-generic-provider-input/5','mission-generic-provider-input/6'].includes(providerInputContract?.schema_version)?(directorOutput32(work)?330000:240000):PROVIDER.timeout_ms))
