  diagnostic.usage_state=metrics?'VALID':(x.usage==null?'MISSING':'INVALID');
  const result={status:x.status,raw_output:null,metrics,terminal:true};
  if(x.status!=='completed'){if(typeof onRawOutput==='function'){const captured=JSON.stringify(x.output??null);result.raw_output=captured;try{await onRawOutput({raw_output:captured,status:x.status,metrics,response_id:diagnostic.response_id,request_id:diagnostic.request_id});}catch{throw fail('MISSION_PROVIDER_OUTPUT_RETENTION_FAILED',result);}}throw fail({incomplete:'MISSION_PROVIDER_INCOMPLETE',failed:'MISSION_PROVIDER_FAILED',cancelled:'MISSION_PROVIDER_CANCELLED'}[x.status],result);}
  let raw=null,parse='MISSING';
  if(Array.isArray(x.output)){
   const messages=x.output.filter(o=>o?.type==='message');
   if(x.output.some(o=>!record(o)||!['message','reasoning'].includes(o.type)))parse='UNKNOWN_TYPE';
   else if(messages.length>1)parse='MULTIPLE';
   else if(messages.length===1){
    const content=messages[0].content;
    if(!Array.isArray(content))parse='MALFORMED';
    else if(content.some(c=>c?.type==='refusal'))parse='REFUSAL';
    else if(content.some(c=>!record(c)||c.type!=='output_text'))parse='UNKNOWN_TYPE';
    else if(content.length>1)parse='MULTIPLE';
    else if(content.length===1&&typeof content[0].text==='string'&&content[0].text.trim().length>0){raw=content[0].text;parse='VALID';}
   }
  }else if(x.output!==undefined&&x.output!==null)parse='MALFORMED';
  diagnostic.parse_state=parse;
  result.raw_output=raw;
  if(typeof onRawOutput==='function'){const captured=raw??JSON.stringify(x.output??null);result.raw_output=captured;try{await onRawOutput({raw_output:captured,status:x.status,metrics,response_id:diagnostic.response_id,request_id:diagnostic.request_id});}catch{throw fail('MISSION_PROVIDER_OUTPUT_RETENTION_FAILED',result);}}
  if(parse!=='VALID')throw fail('PROVIDER_SCHEMA',result);
  let realization;
  try{realization=JSON.parse(raw);}catch{diagnostic.parse_state='MALFORMED';throw fail('PROVIDER_SCHEMA',result);}
  if(metrics===null)throw fail('PROVIDER_SCHEMA',result);
  return {realization,status:x.status,raw_output:raw,metrics,terminal:true};
 }};
}
